-- User-supplied operating information, 2026-11-06. No address/menu/coordinate changes.
-- Missing holidays remain unchanged. Conflicting and unconfirmed statements are retained.
begin;
set local lock_timeout = '5s';
create temp table _operating_input on commit drop as
select * from jsonb_to_recordset($operating$[{"number":1,"name":"3대 기장산 곰장어","hours":"월~일 10:00–22:00","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"kkomjangeo","index":12}]},{"number":2,"name":"개금밀면","hours":"월~일 11:00–20:00","holiday":"확인 필요 (제공 자료에 월~일 휴무로 기재되어 월~일 영업시간 안내와 상충)","links":[{"food":"milmyeon","index":8}]},{"number":3,"name":"개미집","hours":"24시간 영업","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"nakgopsae","index":6}]},{"number":4,"name":"개미집 본점","hours":"월~일 11:00–21:00","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"nakgopsae","index":3}]},{"number":5,"name":"고래사어묵 해운대점","hours":"월·화·수·목·일 09:00–21:00 / 금 09:00–21:30 / 토 09:00–22:00","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"eomuk","index":1}]},{"number":6,"name":"국제밀면","hours":"월~일 10:00–20:00","holiday":"확인 필요","links":[{"food":"milmyeon","index":3}]},{"number":7,"name":"기장곰장어","hours":"확인 필요","holiday":"확인 필요","links":[{"food":"kkomjangeo","index":3}]},{"number":8,"name":"남포동 씨앗호떡","hours":"10:00-23:00","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"ssiat-hotteok","index":2}]},{"number":9,"name":"남포동 육소문","hours":"16:00– 01:00","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"daegu-napjak-mandu","index":0}]},{"number":10,"name":"다래분식","hours":"월~일 09:00–19:30","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"daegu-napjak-mandu","index":1}]},{"number":11,"name":"다원정 한우소고기국밥 동아대병원점","hours":"월-금 08:00-20:00 일 08:30-20:00(Last order 19:30)","holiday":"매주 토요일","links":[{"food":"sogogi-gukbap","index":1}]},{"number":12,"name":"달봉이횟집","hours":"영업일 12:00–21:00 (Last order 19:30)","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"jagalchi-hoe","index":2}]},{"number":13,"name":"대게만찬 기장점","hours":"11:00 - 21:40 (Last order 20:30)","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"gijang-daege","index":2}]},{"number":14,"name":"대도회관","hours":"월~일 11:30–23:00(Last order 22:30)","holiday":"정기휴무 없음 (월~일 영업)","links":[{"food":"mungtigi","index":2}]},{"number":15,"name":"대박집","hours":"월~일 15:00–24:00","holiday":"정기휴